from itertools import combinations_with_replacement

def check_m(m):
    # For each multiset x of size m from {0, 1, ..., m-1}
    # check if sum(x) % m == 0 or there's a permutation sigma such that sum(i * x_sigma(i)) % m == 0
    # To make it faster, let's use DP to check the permutation condition.

    for x in combinations_with_replacement(range(m), m):
        if sum(x) % m == 0:
            continue

        # Now check if there's a permutation p of x such that sum_{i=1}^m i * p[i-1] % m == 0
        # Use DP: dp[i][s] is the set of multisets of size i that can produce sum i*p[i-1] % m = s
        # This is still too much.
        # But we only need to know if *any* permutation works.
        # The residues in x are fixed.
        # Let the sorted residues be x_1, x_2, ..., x_m.
        # We want to know if there's a permutation p of x such that sum_{i=1}^m i * p[i-1] \equiv 0 (mod m).

        # Let's use a recursive function with memoization.
        memo = {}

        # x is a sorted tuple
        def can_sum(idx, current_sum, remaining_x):
            state = (idx, current_sum, remaining_x)
            if state in memo:
                return memo[state]

            if idx == m:
                return current_sum == 0

            # Try all distinct values in remaining_x
            for i in range(len(remaining_x)):
                if i > 0 and remaining_x[i] == remaining_x[i-1]:
                    continue

                new_remaining = remaining_x[:i] + remaining_x[i+1:]
                if can_sum(idx + 1, (current_sum + (idx + 1) * remaining_x[i]) % m, new_remaining):
                    memo[state] = True
                    return True

            memo[state] = False
            return False

        if not can_sum(0, 0, tuple(sorted(x))):
            return False
    return True

for m in range(2, 21):
    if check_m(m):
        print(f"m={m} is a solution")
    else:
        print(f"m={m} is NOT a solution")

def count_solutions():
    count = 0
    for m in range(2, 2001):
        # A solution if m is odd or m is a power of 2
        if m % 2 != 0 or (m > 0 and (m & (m - 1)) == 0):
            count += 1
    return count

